// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, address recipient, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(address(c), amount);
        vm.deal(actor, 0);
        vm.prank(actor);
        bool ok = true;
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
